def type_infer(x):
    """
    Attempts to guess the data type of a string.

    :param x: String to be type inferred.
    :return: Value with correct type, or the original string if no conversion possible.
    """
    try:
        return int(x)
    except ValueError:
        try:
            return float(x)
        except ValueError:
            if x in ('True', 'False'):
                return bool(x == 'True')
            return x
